package com.andye.warmod.radar.station;import com.andye.warmod.WarMod;import com.andye.warmod.block.entity.RadarStationBlockEntity;import com.andye.warmod.radar.station.network.RadarStationNetworking;import java.util.*;import net.fabricmc.fabric.api.event.lifecycle.v1.*;import net.minecraft.SharedConstants;import net.minecraft.server.level.ServerLevel;public final class RadarStationManager {private static final Set<ServerLevel>RESTORED=Collections.synchronizedSet(new HashSet<>());private static boolean registered;private RadarStationManager(){}public static void registerLifecycle(){if(registered)return;ServerTickEvents.END_LEVEL_TICK.register(level->{if(RESTORED.add(level))for(var r:RadarStationSavedData.get(level).records())RadarStationChunkTicketManager.register(level,r.radarId(),r.centre());RadarStationTrackingService.tick(level);});ServerLifecycleEvents.SERVER_STOPPED.register(server->{RESTORED.clear();RadarStationChunkTicketManager.clear();});registered=true;}public static boolean canPlace(ServerLevel l){return RadarStationSavedData.get(l).size()<RadarStationConstants.MAX_RADAR_STATIONS_PER_LEVEL;}public static boolean register(ServerLevel l,RadarStationBlockEntity r){if(!RadarStationChunkTicketManager.register(l,r.radarId(),r.getBlockPos()))return false;updateRecord(r);if(SharedConstants.IS_RUNNING_IN_IDE)WarMod.LOGGER.info("Radar station {} placed at {}",r.radarId(),r.getBlockPos());return true;}public static void updateRecord(RadarStationBlockEntity r){if(r.getLevel()instanceof ServerLevel l)RadarStationSavedData.get(l).put(new RadarStationRecord(r.radarId(),r.getBlockPos(),r.ownerId()==null?new UUID(0,0):r.ownerId(),r.ownerName(),r.warningRadius(),r.phaseOffset()));}public static void unregister(ServerLevel l,RadarStationBlockEntity r){RadarStationNetworking.closeStation(r.radarId());RadarStationChunkTicketManager.unregister(l,r.radarId());RadarStationSavedData.get(l).remove(r.radarId());}}